    questions = []
    rng = random.Random(19191)
    answer_positions = [0, 1, 2, 3] * 3 + [0, 1, 2]
    rng.shuffle(answer_positions)
    for n, (topic, stem, options, explanation) in enumerate(rows, 1):
        order = options[1:]
        rng.shuffle(order)
        order.insert(answer_positions[n - 1], options[0])
        key_map = {chr(65 + i): chr(65 + order.index(text)) for i, text in enumerate(options)}
        questions.append({"id": f"fm-19-choice-{n:03d}", "topic": f"责任会计—{topic}", "stem": stem,
                          "options": [{"key": chr(65 + i), "text": text} for i, text in enumerate(order)],
                          "answer": [key_map["A"]], "explanation": re.sub(r"[A-D]", lambda m: key_map[m.group()], explanation),
                          "type": "single", "difficulty": "进阶", "sourceType": "original",
                          "source": "原创实务情境题；按讲义第19章考点设计", "year": None, "page": None,
                          "tags": [f"责任会计—{topic}"], "authoringMethod": "manual", "decisionTask": topic})
